#include "KS/SRC/stringx.h"

class PanelAnim;

class matrix4x4 {
    float values[16] __attribute__((aligned(16)));
};

struct nglQuadVertex {
    float X;
    float Y;
    float U;
    float V;
    unsigned int Color;
};

struct nglTexture;

struct nglQuad {
    nglQuadVertex Verts[4];
    float Z;
    unsigned int MapFlags;
    unsigned int BlendMode;
    unsigned int BlendModeConstant;
    nglTexture *Tex;
};

struct recti {
    int x0;
    int y0;
    int x1;
    int y1;
};

class PanelQuad {
protected:
    bool isAnim;
    int fade;
    float fade_alpha;
    float fade_timer;
    float mask;
    int maskType;
    PanelAnim *anim;
    nglQuad quad;
    bool drawOn;
    int rotate;
    float rotation;
    float rotate_x;
    float rotate_y;
    int layer;
    float r;
    float g;
    float b;
    float a;
    float x1;
    float y1;
    float x2;
    float y2;
    float width;
    float height;
    float width_a;
    float height_a;
    matrix4x4 matrix;
    bool on_menu;
    bool clip;
    recti clipping;

public:
    matrix4x4 Xform;
    stringx name;
    bool dont_draw;
    float z;
    float u1;
    float v1;
    float u2;
    float v2;
    PanelQuad *next;

    virtual ~PanelQuad();
};

class PanelQuad4 : public PanelQuad {
    float x[4];
    float y[4];
    float u[4];
    float v[4];

public:
    virtual ~PanelQuad4();
};

struct myVector2d {
    float x;
    float y;
};

struct PathData {
    int beach1;
    int beach2;
    int num_points;
    myVector2d points[70];
};

struct vector2d {
    float x;
    float y;
};

class MapData {
public:
    struct MapBeach {
        bool desc_at_right;
        vector2d loc2d;
    };

    MapBeach *beaches;
    int *west_east_order;

private:
    int num_paths;
    PathData *paths;
    int max_pqs;
    PanelQuad4 *copy;
    PanelQuad4 *array;
    PathData *chosen_path;

public:
    ~MapData();
};

__asm__(".equ __builtin_vec_delete, 0x002AC6D0");
__asm__(".equ __builtin_delete, 0x002AC6B0");

MapData::~MapData()
{
	delete[] array;
	delete[] west_east_order;
	delete[] beaches;
	delete[] paths;
	delete copy;
}
